codeExamples.code:
-- Fast: deallocates pages, minimal logging, resets identity
TRUNCATE TABLE staging_orders;

-- Slow: logs and removes each row, keeps identity counter, fires triggers
DELETE FROM staging_orders;

-- DELETE can target a subset; TRUNCATE cannot
DELETE FROM staging_orders WHERE order_date < '2023-01-01';

-- Blocked if child tables reference customers via FK
TRUNCATE TABLE customers;
-- ERROR: cannot truncate a table referenced in a foreign key constraint

-- PostgreSQL: cascade to referencing tables
TRUNCATE TABLE customers CASCADE;

-- PostgreSQL: keep identity values instead of resetting
TRUNCATE TABLE customers RESTART IDENTITY;   -- reset (default)
TRUNCATE TABLE customers CONTINUE IDENTITY;   -- keep current values

-- MySQL: truncate child tables first (no CASCADE for TRUNCATE)
TRUNCATE TABLE orders;
TRUNCATE TABLE customers;

-- MySQL / Oracle: TRUNCATE auto-commits (cannot roll back)
START TRANSACTION;
TRUNCATE TABLE temp_data;   -- implicit commit happens here
ROLLBACK;                    -- no effect; temp_data is already empty

-- PostgreSQL / SQL Server: TRUNCATE is transactional
BEGIN;
TRUNCATE TABLE temp_data;
ROLLBACK;                    -- rows are restored; truncate is undone
